$motionLabel=New-BunnyCaption 'Motion';$motionChoice=[Windows.Controls.ComboBox]::new();$motionChoice.Margin='0,4,0,12';$bunnyControls.MotionChoice=$motionChoice;$settingsStack=$bunnyControls.ThemeChoice.Parent;$settingsStack.Children.Insert(12,$motionLabel);$settingsStack.Children.Insert(13,$motionChoice)
